package org.sleepwell.app;
import android.app.*;import android.content.*;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
/** Private settings and real typed Intent payload only. Never starts a Service. */
public final class ArmedWaitNativeTest {
    interface Task{void run(SharedPreferences preferences)throws Exception;}void fixture(Task task)throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();String name="armed-conditions-"+UUID.randomUUID();Map<String,?> before=new HashMap<>(Prefs.of(c).getAll());try{task.run(c.getSharedPreferences(name,0));}finally{c.deleteSharedPreferences(name);assertEquals(before,Prefs.of(c).getAll());assertFalse(TrackingService.running);assertFalse(AlarmService.active);}}
    @Test public void absentDefaultsAndUnrelatedRecurringChargingDoNotChangeExplicitWait()throws Exception{fixture(p->{p.edit().putBoolean("charging",true).putBoolean("enabled",true).commit();ArmedWaitConditions off=ArmedWaitSettings.read(p);assertFalse(off.charging);assertFalse(off.screenOff);Intent empty=new Intent();assertFalse(ArmedWaitSettings.intent(empty).charging);assertEquals("",off.blocked(false,true));});}
    @Test public void savedConditionsAndArmPayloadFreezeIndependentlyOfLaterPreferenceEdits()throws Exception{fixture(p->{assertTrue(ArmedWaitSettings.put(p.edit(),new ArmedWaitConditions(true,true)).commit());ArmedWaitConditions frozen=ArmedWaitSettings.read(p);Intent request=ArmedWaitSettings.extras(new Intent().setAction(TrackingService.ARM),frozen);assertTrue(ArmedWaitSettings.put(p.edit(),ArmedWaitConditions.NONE).commit());ArmedWaitConditions payload=ArmedWaitSettings.intent(request);assertTrue(frozen.charging);assertTrue(frozen.screenOff);assertTrue(payload.charging);assertTrue(payload.screenOff);assertFalse(ArmedWaitSettings.read(p).charging);assertEquals("WAITING_CHARGING",payload.blocked(false,false));});}
    @Test public void malformedPreferencesOrArmExtrasCannotSilentlyWeakenConditions()throws Exception{fixture(p->{for(String key:new String[]{ArmedWaitSettings.CHARGING,ArmedWaitSettings.SCREEN}){p.edit().clear().putString(key,"true").commit();Map<String,?> raw=new HashMap<>(p.getAll());assertThrows(IllegalArgumentException.class,()->ArmedWaitSettings.read(p));assertEquals(raw,p.getAll());Intent bad=new Intent().putExtra(key,"true");assertThrows(IllegalArgumentException.class,()->ArmedWaitSettings.intent(bad));}assertTrue(ArmedWaitSettings.put(p.edit(),ArmedWaitConditions.NONE).commit());assertFalse(ArmedWaitSettings.read(p).charging);});}
}
